#include <condition_variable>
#include <deque>
#include <mutex>
#include <optional>

class JobQueue
{
public:
    void push(int job)
    {
        {
            std::lock_guard lock{ m_mutex };
            m_jobs.push_back(job);
        }
        m_ready.notify_one();
    }

    std::optional<int> pop()
    {
        std::unique_lock lock{ m_mutex };
        m_ready.wait(lock, [this] { return !m_jobs.empty() || m_closed; });   // sleeps until there is a reason to wake
        if (m_jobs.empty()) return std::nullopt;                             // closed and drained
        const int job{ m_jobs.front() };
        m_jobs.pop_front();
        return job;
    }

    std::optional<int> tryPop()
    {
        std::lock_guard lock{ m_mutex };
        if (m_jobs.empty()) return std::nullopt;
        const int job{ m_jobs.front() };
        m_jobs.pop_front();
        return job;
    }

    void close()
    {
        {
            std::lock_guard lock{ m_mutex };
            m_closed = true;
        }
        m_ready.notify_all();
    }

private:
    std::mutex m_mutex;
    std::condition_variable m_ready;
    std::deque<int> m_jobs;
    bool m_closed{ false };
};

