#include <atomic>
#include <chrono>
#include <thread>
#include <vector>
TEST("first in, first out") { JobQueue q; q.push(1); q.push(2); CHECK_EQ(*q.tryPop(), 1); CHECK_EQ(*q.pop(), 2); CHECK(!q.tryPop().has_value()); }
TEST("closed and empty returns nothing") { JobQueue q; q.close(); CHECK(!q.pop().has_value()); }
TEST("queued jobs survive closing") { JobQueue q; q.push(5); q.close(); CHECK_EQ(*q.pop(), 5); CHECK(!q.pop().has_value()); }
TEST("a worker waits for a job")
{
    JobQueue q;
    std::atomic<int> got{ 0 };
    std::thread worker{ [&] { if (auto j{ q.pop() }) got = *j; } };
    std::this_thread::sleep_for(std::chrono::milliseconds(50));
    q.push(42);
    worker.join();
    CHECK_EQ(got.load(), 42);
}
TEST("four workers share 10,000 jobs exactly once")
{
    JobQueue q;
    std::atomic<long long> sum{ 0 };
    std::atomic<int> count{ 0 };
    std::vector<std::thread> workers;
    for (int w{ 0 }; w < 4; ++w)
        workers.emplace_back([&] { while (auto j{ q.pop() }) { sum += *j; ++count; } });
    for (int i{ 1 }; i <= 10000; ++i) q.push(i);
    q.close();
    for (auto& t : workers) t.join();
    CHECK_EQ(count.load(), 10000);
    CHECK_EQ(sum.load(), 50005000LL);
}
TEST("closing wakes idle workers") { JobQueue q; std::thread a{ [&] { q.pop(); } }, b{ [&] { q.pop(); } }; std::this_thread::sleep_for(std::chrono::milliseconds(30)); q.close(); a.join(); b.join(); CHECK(true); }

